/**
 * Cuentas del parqueadero — lógica compartida.
 *
 * Este archivo es la FUENTE DE VERDAD de toda la lógica: interpretar los
 * comandos de Telegram, calcular saldos y armar las respuestas. Los nodos
 * Code de n8n no traen este código: se les inyecta con `build.ps1`.
 *
 *   1. Se edita ACÁ.
 *   2. Se corre `pwsh n8n/build.ps1` (o `powershell -File n8n/build.ps1`).
 *   3. Se importan de nuevo los JSON de `n8n/workflows/` en n8n.
 *
 * Editar el JSON a mano funciona hasta la próxima compilación, que lo pisa.
 *
 * Sin dependencias y sin `require`: los nodos Code de n8n corren en un
 * sandbox donde no hay ni una ni otro.
 *
 * Probado con `node --test n8n/src/pruebas.js`, contra los CSV de
 * ../datos/. Falta la prueba de punta a punta —T6 de ../TAREAS.md, con la
 * hoja real y n8n de por medio—, pero los cálculos ya están cubiertos.
 */

/** America/Bogota: UTC-5 fijo, sin horario de verano. */
const OFFSET_HORAS = -5;

/** Cuántos dígitos lleva el correlativo de recaudos y gastos. */
const ANCHO_ID = 6;

// ────────────────────────────────────────────────────────────
//  Utilidades
// ────────────────────────────────────────────────────────────

function pad2(n) {
  return String(n).padStart(2, '0');
}

/** Minúsculas, sin tildes, sin espacios sobrantes. */
function normalizar(s) {
  return String(s === null || s === undefined ? '' : s)
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .trim();
}

/**
 * La fecha de hoy en Bogotá, como AAAA-MM-DD.
 * n8n corre en UTC; sin este ajuste, todo lo que se registre entre las 19:00
 * y la medianoche queda con la fecha del día siguiente.
 */
function hoyEnBogota(ahora) {
  const base = ahora instanceof Date ? ahora : new Date();
  return new Date(base.getTime() + OFFSET_HORAS * 3600 * 1000)
    .toISOString()
    .slice(0, 10);
}

function esFechaReal(iso) {
  const d = new Date(iso + 'T00:00:00Z');
  return !isNaN(d.getTime()) && d.toISOString().slice(0, 10) === iso;
}

function sumarDias(iso, n) {
  const d = new Date(iso + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
}

function diasEntre(desde, hasta) {
  const a = new Date(desde + 'T00:00:00Z').getTime();
  const b = new Date(hasta + 'T00:00:00Z').getTime();
  return Math.round((b - a) / 86400000);
}

const MESES = [
  'enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio',
  'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre',
];

/** 480000 → "$480.000" */
function fmtCOP(n) {
  const v = Math.round(Number(n) || 0);
  const signo = v < 0 ? '-' : '';
  const s = String(Math.abs(v)).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  return signo + '$' + s;
}

/** "2026-08-22" → "22-08" */
function fmtFechaCorta(iso) {
  const p = String(iso || '').split('-');
  return p.length === 3 ? p[2] + '-' + p[1] : String(iso || '');
}

/**
 * Lo que devuelve Google Sheets puede ser número o texto ("480.000", "$480.000").
 * Los puntos se tratan como separador de miles: en COP no se usan centavos.
 */
function num(v) {
  if (typeof v === 'number') return Number.isFinite(v) ? v : 0;
  const t = String(v === null || v === undefined ? '' : v)
    .replace(/[^\d,.\-]/g, '')
    .replace(/\./g, '')
    .replace(',', '.');
  const n = parseFloat(t);
  return Number.isFinite(n) ? n : 0;
}

/** Vacío de verdad: Sheets devuelve '' o undefined según el nodo. */
function vacio(v) {
  return v === null || v === undefined || String(v).trim() === '';
}

/**
 * "480000" | "480.000" | "480k" | "1.2m" → 480000 | 1200000
 * Devuelve null si no es un monto. No acepta negativos: las anulaciones las
 * genera el sistema, no se escriben a mano.
 */
function parsearMonto(txt) {
  let t = normalizar(txt).replace(/\$/g, '').replace(/\s/g, '');
  if (!t) return null;

  let mult = 1;
  const suf = t.match(/^([\d.,]+)(k|m)$/);
  if (suf) {
    t = suf[1];
    mult = suf[2] === 'k' ? 1000 : 1000000;
    t = t.replace(',', '.');
  } else {
    // Sin sufijo, los puntos y comas son separadores de miles.
    t = t.replace(/[.,]/g, '');
  }

  if (!/^\d+(\.\d+)?$/.test(t)) return null;
  const n = Math.round(parseFloat(t) * mult);
  return Number.isFinite(n) && n >= 0 ? n : null;
}

/**
 * "22-08" | "22/08" | "22-08-2026" | "2026-08-22" | "hoy" | "ayer" → AAAA-MM-DD
 * Devuelve null si no es una fecha. El formato del día a día es DD-MM.
 */
function parsearFecha(txt, hoy) {
  const t = normalizar(txt);
  if (!t) return null;

  if (t === 'hoy') return hoy;
  if (t === 'ayer') return sumarDias(hoy, -1);
  if (t === 'antier' || t === 'anteayer') return sumarDias(hoy, -2);

  if (/^\d{4}-\d{2}-\d{2}$/.test(t)) return esFechaReal(t) ? t : null;

  const m = t.match(/^(\d{1,2})[-/](\d{1,2})(?:[-/](\d{2,4}))?$/);
  if (!m) return null;

  const dia = Number(m[1]);
  const mes = Number(m[2]);
  let anio = m[3] ? Number(m[3]) : Number(hoy.slice(0, 4));
  if (anio < 100) anio += 2000;
  if (mes < 1 || mes > 12 || dia < 1 || dia > 31) return null;

  const iso = anio + '-' + pad2(mes) + '-' + pad2(dia);
  return esFechaReal(iso) ? iso : null;
}

function idJornada(fecha) {
  return 'J-' + fecha;
}

/** El siguiente correlativo: R-000105 → R-000106 */
function siguienteId(prefijo, filas) {
  let max = 0;
  const re = new RegExp('^' + prefijo + '(\\d+)$');
  for (const f of filas) {
    const m = String((f && f.id) || '').match(re);
    if (m) max = Math.max(max, Number(m[1]));
  }
  return prefijo + String(max + 1).padStart(ANCHO_ID, '0');
}

// ────────────────────────────────────────────────────────────
//  Cálculos
// ────────────────────────────────────────────────────────────

/** { 'J-2026-08-22': 300000, ... } */
function recaudadoPorJornada(recaudos) {
  const acc = {};
  for (const r of recaudos) {
    const k = String((r && r.jornada_id) || '');
    if (!k) continue;
    acc[k] = (acc[k] || 0) + num(r.monto);
  }
  return acc;
}

/**
 * Ojo con el orden: una jornada de causado 0 (un día que no abrió) queda
 * SALDADA, no pendiente. No debe nada.
 */
function estadoJornada(causado, recaudado) {
  if (recaudado > causado) return 'sobrante';
  if (recaudado === causado) return 'saldado';
  if (recaudado === 0) return 'pendiente';
  return 'parcial';
}

const ICONO_ESTADO = {
  saldado: '🟢',
  parcial: '🟡',
  pendiente: '🟠',
  sobrante: '⚠️',
};

function buscarJornada(jornadas, fecha) {
  const id = idJornada(fecha);
  return jornadas.find((j) => String(j.id) === id) || null;
}

/** El detalle de una jornada, con su saldo y su estado. */
function detalleJornada(jornada, recaudos, hoy) {
  const causado = num(jornada.causado);
  const recaudado = (recaudadoPorJornada(recaudos)[String(jornada.id)] || 0);
  return {
    id: String(jornada.id),
    fecha: String(jornada.fecha),
    causado: causado,
    recaudado: recaudado,
    saldo: causado - recaudado,
    estado: estadoJornada(causado, recaudado),
    dias: diasEntre(String(jornada.fecha), hoy),
    nota: jornada.nota || '',
  };
}

/**
 * Todo lo que falta por cobrar, del día más viejo al más nuevo.
 * No tiene mes: es un acumulado a hoy.
 */
function calcularCartera(jornadas, recaudos, hoy) {
  const rec = recaudadoPorJornada(recaudos);
  const items = [];

  for (const j of jornadas) {
    if (vacio(j.fecha)) continue;
    const causado = num(j.causado);
    const recaudado = rec[String(j.id)] || 0;
    const saldo = causado - recaudado;
    if (saldo > 0) {
      items.push({
        id: String(j.id),
        fecha: String(j.fecha),
        causado: causado,
        recaudado: recaudado,
        saldo: saldo,
        dias: diasEntre(String(j.fecha), hoy),
      });
    }
  }

  items.sort((a, b) => (a.fecha < b.fecha ? -1 : a.fecha > b.fecha ? 1 : 0));
  return {
    items: items,
    total: items.reduce((s, i) => s + i.saldo, 0),
  };
}

/**
 * Los días del mes que no tienen jornada registrada.
 * El día de hoy no cuenta: lo normal es que se reporte mañana.
 */
function diasSinReportar(jornadas, anio, mes, hoy) {
  const pre = anio + '-' + pad2(mes);
  const vistos = {};
  for (const j of jornadas) {
    if (String(j.fecha || '').indexOf(pre) === 0) vistos[String(j.fecha)] = true;
  }

  const faltan = [];
  const ultimoDia = new Date(Date.UTC(anio, mes, 0)).getUTCDate();
  for (let d = 1; d <= ultimoDia; d++) {
    const iso = pre + '-' + pad2(d);
    if (iso >= hoy) break;
    if (!vistos[iso]) faltan.push(iso);
  }
  return faltan;
}

/**
 * Las cifras del mes.
 *
 *   resultado = causado − gastos causados      ¿el negocio va bien?
 *   caja      = recaudado − gastos pagados     ¿tengo plata?
 *
 * Casi nunca dan igual, y eso es correcto: la diferencia es el movimiento de
 * la cartera.
 */
function resumenMes(datos, anio, mes, hoy) {
  const pre = anio + '-' + pad2(mes);
  const enMes = (f) => String(f || '').indexOf(pre) === 0;
  const suma = (filas, campo) => filas.reduce((s, f) => s + num(f.monto || f[campo]), 0);

  const jornadas = datos.jornadas.filter((j) => enMes(j.fecha));
  const causado = jornadas.reduce((s, j) => s + num(j.causado), 0);

  const gastosCausados = datos.gastos.filter((g) => enMes(g.fecha));
  const gastosPagados = datos.gastos.filter((g) => enMes(g.fecha_pago));
  const recaudos = datos.recaudos.filter((r) => enMes(r.fecha));

  const gastado = suma(gastosCausados, 'monto');
  const salio = suma(gastosPagados, 'monto');
  const entro = suma(recaudos, 'monto');

  const cartera = calcularCartera(datos.jornadas, datos.recaudos, hoy);
  const faltantes = diasSinReportar(datos.jornadas, anio, mes, hoy);

  return {
    anio: anio,
    mes: mes,
    nombreMes: MESES[mes - 1],
    diasRegistrados: jornadas.length,
    faltantes: faltantes,
    causado: causado,
    gastado: gastado,
    resultado: causado - gastado,
    entro: entro,
    salio: salio,
    caja: entro - salio,
    cartera: cartera.total,
    carteraDias: cartera.items.length,
    porCategoria: gastosPorCategoria(gastosCausados),
  };
}

/**
 * La serie diaria que alimenta la gráfica del portal.
 *
 * Ojo con `recaudado`, que es lo fácil de equivocar: acá es **por fecha de
 * caja** —cuánta plata entró ese día, sin importar qué jornada saldaba— y no
 * por jornada, como en `detalleJornada`. Es al revés a propósito: el
 * corrimiento entre la barra de causado y la de recaudado es justamente lo
 * que la gráfica existe para mostrar.
 *
 *   causado   null  = no hay jornada registrada ese día (no se sabe)
 *             0     = la jornada existe y no produjo (no abrió)
 *   gastado   por fecha de causación del gasto, no de pago
 *
 * Va del día 1 hasta el último del mes, o hasta hoy si el mes es el corriente.
 *
 * Invariante: la suma de `recaudado` da `resumenMes(...).entro`, salvo que
 * hubiera recaudos con fecha futura — cosa que el bot no puede generar,
 * porque siempre los registra con la fecha de hoy.
 */
function seriePorDia(datos, anio, mes, hoy) {
  const pre = anio + '-' + pad2(mes);
  const ultimoDia = new Date(Date.UTC(anio, mes, 0)).getUTCDate();
  const salida = [];

  for (let d = 1; d <= ultimoDia; d++) {
    const iso = pre + '-' + pad2(d);
    if (iso > hoy) break;

    const jornada = (datos.jornadas || []).find((j) => String(j.fecha) === iso);
    salida.push({
      fecha: iso,
      causado: jornada ? num(jornada.causado) : null,
      recaudado: (datos.recaudos || [])
        .filter((r) => String(r.fecha) === iso)
        .reduce((s, r) => s + num(r.monto), 0),
      gastado: (datos.gastos || [])
        .filter((g) => String(g.fecha) === iso)
        .reduce((s, g) => s + num(g.monto), 0),
    });
  }
  return salida;
}

function gastosPorCategoria(gastos) {
  const acc = {};
  for (const g of gastos) {
    const c = normalizar(g.categoria) || 'otros';
    acc[c] = (acc[c] || 0) + num(g.monto);
  }
  return Object.keys(acc)
    .map((c) => ({ categoria: c, monto: acc[c] }))
    .sort((a, b) => b.monto - a.monto);
}

// ────────────────────────────────────────────────────────────
//  Configuración (pestaña `config`)
// ────────────────────────────────────────────────────────────

/**
 * Las filas clave/valor de `config` a un objeto manejable.
 * `chat_autorizado` puede repetirse: así entra un segundo chat sin tocar código.
 */
function leerConfig(filas) {
  const cfg = {
    categorias: [],
    medios: [],
    chats: [],
    diasAlertaCartera: 3,
    horaRecordatorio: 9,
    nombre: 'el parqueadero',
  };

  for (const f of filas || []) {
    const clave = normalizar(f.clave);
    const valor = String(f.valor === null || f.valor === undefined ? '' : f.valor).trim();
    if (!clave || !valor) continue;

    if (clave === 'categoria') cfg.categorias.push(normalizar(valor));
    else if (clave === 'medio') cfg.medios.push(normalizar(valor));
    else if (clave === 'chat_autorizado') cfg.chats.push(valor);
    else if (clave === 'dias_alerta_cartera') cfg.diasAlertaCartera = num(valor) || 3;
    else if (clave === 'hora_recordatorio') cfg.horaRecordatorio = num(valor);
    else if (clave === 'nombre') cfg.nombre = valor;
  }

  if (!cfg.categorias.length) cfg.categorias = ['servicios', 'nomina', 'insumos', 'mantenimiento', 'arriendo', 'impuestos', 'otros'];
  if (!cfg.medios.length) cfg.medios = ['efectivo', 'nequi', 'transferencia', 'daviplata'];
  return cfg;
}

/**
 * Un chat sin autorizar no recibe respuesta: contestarle "no tenés permiso"
 * le confirma a un desconocido que el bot existe y qué hace.
 */
function estaAutorizado(chatId, cfg) {
  const id = String(chatId || '').trim();
  if (!id) return false;
  return cfg.chats.indexOf(id) !== -1;
}

// ────────────────────────────────────────────────────────────
//  Parser de comandos
// ────────────────────────────────────────────────────────────

/**
 * Reparte los argumentos sin depender del orden: cada token se clasifica por
 * su forma. Una fecha lleva separador ("22-08"), un monto no ("480000"), así
 * que no hay ambigüedad y da lo mismo escribir `/dia 22-08 480000` que
 * `/dia 480000 22-08`.
 */
function repartirArgs(args, hoy, cfg) {
  const out = { fecha: null, monto: null, medio: null, resto: [] };

  for (const bruto of args) {
    const tok = String(bruto).trim();
    if (!tok) continue;

    if (out.fecha === null) {
      const f = parsearFecha(tok, hoy);
      if (f) { out.fecha = f; continue; }
    }
    if (out.monto === null) {
      const m = parsearMonto(tok);
      if (m !== null) { out.monto = m; continue; }
    }
    if (out.medio === null && cfg && cfg.medios.indexOf(normalizar(tok)) !== -1) {
      out.medio = normalizar(tok);
      continue;
    }
    out.resto.push(tok);
  }
  return out;
}

function errorCmd(mensaje) {
  return { tipo: 'error', mensaje: mensaje };
}

/**
 * Texto de Telegram → intención.
 * Nunca escribe nada ni consulta la hoja: solo interpreta.
 */
function parsearComando(texto, hoy, cfg) {
  const bruto = String(texto || '').trim();
  if (!bruto) return { tipo: 'ayuda' };

  const partes = bruto.split(/\s+/);
  const cmd = normalizar(partes[0]).replace(/^\//, '').replace(/@.*$/, '');
  const args = partes.slice(1);
  const a = repartirArgs(args, hoy, cfg);

  switch (cmd) {
    case 'dia':
    case 'jornada': {
      const fecha = a.fecha || hoy;
      if (a.monto === null) return { tipo: 'consultar_dia', fecha: fecha };
      return { tipo: 'dia', fecha: fecha, monto: a.monto, nota: a.resto.join(' ') };
    }

    case 'recibo':
    case 'recibi':
    case 'recaudo': {
      if (a.monto === null) {
        return errorCmd('Falta el monto.\nEjemplo: /recibo 300000 22-08');
      }
      return {
        tipo: 'recibo',
        fecha: a.fecha,           // null = repartir desde la jornada más vieja
        monto: a.monto,
        medio: a.medio || 'efectivo',
        nota: a.resto.join(' '),
      };
    }

    case 'gasto':
    case 'deuda': {
      if (a.monto === null) {
        return errorCmd('Falta el monto.\nEjemplo: /gasto 45000 servicios agua agosto');
      }
      const categoria = a.resto.length ? normalizar(a.resto[0]) : '';
      if (!categoria) {
        return errorCmd('Falta la categoría.\nHay: ' + cfg.categorias.join(', '));
      }
      if (cfg.categorias.indexOf(categoria) === -1) {
        return errorCmd('No conozco la categoría "' + categoria + '".\nHay: ' + cfg.categorias.join(', '));
      }
      return {
        tipo: 'gasto',
        fecha: a.fecha || hoy,
        monto: a.monto,
        categoria: categoria,
        descripcion: a.resto.slice(1).join(' '),
        pagado: cmd === 'gasto',   // /deuda deja fecha_pago vacío
      };
    }

    case 'saldo':
    case 'hoy':
      return { tipo: 'saldo' };

    case 'pendientes':
    case 'cartera':
      return { tipo: 'pendientes' };

    case 'mes': {
      let anio = Number(hoy.slice(0, 4));
      let mes = Number(hoy.slice(5, 7));
      if (a.fecha) {
        anio = Number(a.fecha.slice(0, 4));
        mes = Number(a.fecha.slice(5, 7));
      } else if (a.resto.length || a.monto !== null) {
        const t = normalizar(a.resto[0] !== undefined ? a.resto[0] : String(a.monto));
        const porNombre = MESES.indexOf(t);
        if (porNombre !== -1) mes = porNombre + 1;
        else if (/^\d{1,2}$/.test(t) && Number(t) >= 1 && Number(t) <= 12) mes = Number(t);
        else return errorCmd('No entendí el mes. Probá /mes 07 o /mes julio');
      }
      return { tipo: 'mes', anio: anio, mes: mes };
    }

    case 'anular': {
      const id = (a.resto[0] || '').toUpperCase().trim();
      if (!/^[RG]-\d+$/.test(id)) {
        return errorCmd('Decime cuál anular.\nEjemplo: /anular R-000101\nCon /ultimos ves los ids.');
      }
      return { tipo: 'anular', id: id };
    }

    case 'ultimos':
    case 'ultimo':
      return { tipo: 'ultimos' };

    case 'ayuda':
    case 'start':
    case 'help':
      return { tipo: 'ayuda' };

    default:
      // Texto suelto. Si es solo un número, casi seguro quiso registrar algo
      // pero no dijo qué: preguntar en vez de adivinar.
      if (parsearMonto(bruto) !== null) {
        return errorCmd(
          'No sé qué es ' + fmtCOP(parsearMonto(bruto)) + '.\n' +
          '/dia ' + bruto + ' → lo que produjo hoy\n' +
          '/recibo ' + bruto + ' → plata que te entregaron'
        );
      }
      return { tipo: 'ayuda' };
  }
}

// ────────────────────────────────────────────────────────────
//  Decisión: qué escribir y qué contestar
// ────────────────────────────────────────────────────────────

/**
 * Comando + estado actual de la hoja → qué fila(s) escribir y qué responder.
 *
 * Es una función pura: no toca la hoja ni Telegram. Devuelve
 *   { accion, filas, mensaje }
 * y los nodos de n8n se encargan del resto. Toda la lógica de negocio vive
 * acá, en un solo lugar, para que el bot y el portal no puedan discrepar.
 */
function decidir(comando, datos, hoy, cfg) {
  const jornadas = datos.jornadas || [];
  const recaudos = datos.recaudos || [];
  const gastos = datos.gastos || [];

  switch (comando.tipo) {
    // ── registrar lo que produjo un día ──────────────────────
    case 'dia': {
      const existente = buscarJornada(jornadas, comando.fecha);
      const fila = {
        id: idJornada(comando.fecha),
        fecha: comando.fecha,
        causado: comando.monto,
        fuente: comando.fuente || 'telegram',
        registrado_en: hoy,
        nota: comando.nota || (existente ? existente.nota : '') || '',
      };

      // El bot corrige de una y muestra el antes/después en la respuesta; el
      // portal pide confirmación primero, porque su formulario no deja ver
      // que ya había algo.
      const pideConfirmacion = comando.fuente === 'portal' && comando.confirmar !== true;
      if (existente && pideConfirmacion && num(existente.causado) !== comando.monto) {
        const d = detalleJornada(existente, recaudos, hoy);
        return {
          accion: 'responder',
          codigo: 'jornada_existe',
          filas: [],
          jornadaActual: d,
          mensaje: 'Ya hay una jornada del ' + fmtFechaCorta(comando.fecha) + ' con ' +
            fmtCOP(d.causado) + '. Confirmá si querés cambiarla a ' + fmtCOP(comando.monto) + '.',
        };
      }

      if (existente && num(existente.causado) === comando.monto) {
        return {
          accion: 'responder',
          filas: [],
          mensaje: 'Ya estaba así.\n' + lineaJornada(detalleJornada(existente, recaudos, hoy)),
        };
      }

      const recaudado = recaudadoPorJornada(recaudos)[fila.id] || 0;
      const saldo = comando.monto - recaudado;
      const cabeza = existente
        ? 'Corregido  ' + fmtFechaCorta(comando.fecha) + '\n' +
          'Antes ' + fmtCOP(num(existente.causado)) + ' → ahora ' + fmtCOP(comando.monto)
        : 'Anotado  ' + fmtFechaCorta(comando.fecha) + '\n' +
          'Causado ' + fmtCOP(comando.monto);

      let cola = '';
      if (recaudado > 0) {
        cola = '\nRecaudado ' + fmtCOP(recaudado) +
          (saldo > 0 ? ' · faltan ' + fmtCOP(saldo)
            : saldo < 0 ? ' · ⚠️ sobran ' + fmtCOP(-saldo)
              : ' · saldado');
      }

      return {
        accion: existente ? 'actualizar_jornada' : 'anexar_jornada',
        filas: [fila],
        mensaje: cabeza + cola + '\n' + lineaCartera(jornadas, recaudos, hoy, fila),
      };
    }

    // ── registrar plata que llegó ────────────────────────────
    case 'recibo': {
      if (comando.fecha) {
        const j = buscarJornada(jornadas, comando.fecha);
        if (!j) {
          return {
            accion: 'responder',
            filas: [],
            // El texto se adapta a por dónde entró: mandarle la sintaxis de
            // un comando de Telegram a alguien que está en un formulario web
            // es decirle que haga algo que ahí no existe.
            mensaje: 'No tengo la jornada del ' + fmtFechaCorta(comando.fecha) + ', así que no anoté nada.\n' +
              '¿Cuánto produjo ese día?' +
              (comando.fuente === 'portal' ? '' : '\n/dia ' + fmtFechaCorta(comando.fecha) + ' <monto>'),
          };
        }
        const fila = filaRecaudo(recaudos, hoy, j.id, comando);
        const antes = detalleJornada(j, recaudos, hoy);
        const saldo = antes.saldo - comando.monto;

        let mensaje = 'Anotado  ' + fila.id + '\n' +
          'Jornada ' + fmtFechaCorta(j.fecha) + ' · causado ' + fmtCOP(antes.causado) + '\n' +
          'Recaudado ' + fmtCOP(antes.recaudado + comando.monto);

        if (saldo > 0) mensaje += ' · faltan ' + fmtCOP(saldo);
        else if (saldo === 0) mensaje += ' · saldado';
        else {
          mensaje = '⚠️ Anotado, pero revisá\n' +
            'La jornada ' + fmtFechaCorta(j.fecha) + ' quedó con ' + fmtCOP(-saldo) + ' de sobrante.\n' +
            'Causado ' + fmtCOP(antes.causado) + ', recaudado ' + fmtCOP(antes.recaudado + comando.monto) + '.\n' +
            'Puede que el causado esté mal reportado.';
        }

        return {
          accion: 'anexar_recaudo',
          filas: [fila],
          mensaje: mensaje + '\n' + lineaCarteraTras(jornadas, recaudos, hoy, [fila]),
        };
      }

      // Sin fecha: se reparte desde la jornada pendiente más vieja.
      const cartera = calcularCartera(jornadas, recaudos, hoy);
      if (!cartera.items.length) {
        return {
          accion: 'responder',
          filas: [],
          mensaje: 'No hay nada pendiente por cobrar, así que no supe a qué día anotarlo.\n' +
            'Decime el día: /recibo ' + comando.monto + ' ' + fmtFechaCorta(hoy),
        };
      }

      const filas = [];
      let resto = comando.monto;
      const aplicado = [];

      for (const item of cartera.items) {
        if (resto <= 0) break;
        const aplica = Math.min(resto, item.saldo);
        const fila = filaRecaudo(recaudos.concat(filas), hoy, item.id, {
          monto: aplica,
          medio: comando.medio,
          nota: comando.nota || (filas.length ? 'reparto automatico' : ''),
        });
        filas.push(fila);
        aplicado.push({ fecha: item.fecha, monto: aplica, saldo: item.saldo - aplica });
        resto -= aplica;
      }

      let mensaje = 'Anotado ' + fmtCOP(comando.monto);
      if (aplicado.length === 1) {
        const u = aplicado[0];
        mensaje += ' a la jornada del ' + fmtFechaCorta(u.fecha) + '\n' +
          (u.saldo > 0 ? 'Faltan ' + fmtCOP(u.saldo) : 'Saldada');
      } else {
        mensaje += ' repartido en ' + aplicado.length + ' días:\n' +
          aplicado.map((u) => '  ' + fmtFechaCorta(u.fecha) + '  ' + fmtCOP(u.monto) +
            (u.saldo > 0 ? '  (faltan ' + fmtCOP(u.saldo) + ')' : '  ✓')).join('\n');
      }
      if (resto > 0) {
        mensaje += '\n\n⚠️ Sobraron ' + fmtCOP(resto) + ' sin jornada a la cual aplicar.\n' +
          'No los anoté. Registrá el día que falta y volvé a mandarlos.';
      }

      return {
        accion: 'anexar_recaudo',
        filas: filas,
        mensaje: mensaje + '\n' + lineaCarteraTras(jornadas, recaudos, hoy, filas),
      };
    }

    // ── registrar un gasto ───────────────────────────────────
    case 'gasto': {
      const fila = {
        id: siguienteId('G-', gastos),
        fecha: comando.fecha,
        // El bot asume que un gasto se paga el mismo día y sale de caja; el
        // portal tiene campos para las dos cosas y manda lo que se eligió.
        fecha_pago: comando.pagado ? (comando.fechaPago || comando.fecha) : '',
        categoria: comando.categoria,
        monto: comando.monto,
        descripcion: comando.descripcion || '',
        pagado_con: comando.pagado ? (comando.pagadoCon || 'caja') : '',
        soporte: '',
      };
      return {
        accion: 'anexar_gasto',
        filas: [fila],
        mensaje: 'Anotado  ' + fila.id + '\n' +
          (comando.pagado ? 'Gasto ' : 'Deuda ') + fmtCOP(comando.monto) +
          ' · ' + comando.categoria +
          (fila.descripcion ? '\n' + fila.descripcion : '') +
          '\n' + fmtFechaCorta(comando.fecha) +
          (comando.pagado ? '' : ' · sin pagar'),
      };
    }

    // ── anular un recaudo o un gasto ─────────────────────────
    case 'anular': {
      const esRecaudo = comando.id.charAt(0) === 'R';
      const origen = esRecaudo ? recaudos : gastos;
      const original = origen.find((f) => String(f.id).toUpperCase() === comando.id);

      if (!original) {
        return { accion: 'responder', filas: [], mensaje: 'No encuentro ' + comando.id + '. Mirá /ultimos.' };
      }
      if (num(original.monto) < 0) {
        return { accion: 'responder', filas: [], mensaje: comando.id + ' ya es una anulación. No la anulo de nuevo.' };
      }

      const monto = -num(original.monto);
      const fila = esRecaudo
        ? {
            id: siguienteId('R-', recaudos),
            fecha: hoy,
            jornada_id: original.jornada_id,
            monto: monto,
            medio: original.medio || '',
            nota: 'anula ' + comando.id,
          }
        : {
            id: siguienteId('G-', gastos),
            fecha: original.fecha,
            fecha_pago: original.fecha_pago || '',
            categoria: original.categoria,
            monto: monto,
            descripcion: 'anula ' + comando.id,
            pagado_con: original.pagado_con || '',
            soporte: '',
          };

      return {
        accion: esRecaudo ? 'anexar_recaudo' : 'anexar_gasto',
        filas: [fila],
        mensaje: 'Anulado ' + comando.id + ' (' + fmtCOP(-monto) + ')\n' +
          'Quedó registrado como ' + fila.id + ' en negativo. La fila original no se borra.',
      };
    }

    // ── consultas ────────────────────────────────────────────
    case 'consultar_dia': {
      const j = buscarJornada(jornadas, comando.fecha);
      if (!j) {
        return {
          accion: 'responder', filas: [],
          mensaje: 'No hay nada registrado del ' + fmtFechaCorta(comando.fecha) + '.\n' +
            '/dia ' + fmtFechaCorta(comando.fecha) + ' <monto>',
        };
      }
      const d = detalleJornada(j, recaudos, hoy);
      const suyos = recaudos.filter((r) => String(r.jornada_id) === d.id && num(r.monto) !== 0);
      const gastosDia = gastos.filter((g) => String(g.fecha) === d.fecha);

      let m = lineaJornada(d);
      if (suyos.length) {
        m += '\n\nRecaudos:\n' + suyos.map((r) =>
          '  ' + fmtFechaCorta(r.fecha) + '  ' + fmtCOP(num(r.monto)) + '  ' + (r.medio || '')).join('\n');
      }
      if (gastosDia.length) {
        m += '\n\nGastos:\n' + gastosDia.map((g) =>
          '  ' + fmtCOP(num(g.monto)) + '  ' + (g.categoria || '') + '  ' + (g.descripcion || '')).join('\n');
      }
      if (d.nota) m += '\n\n' + d.nota;
      return { accion: 'responder', filas: [], mensaje: m };
    }

    case 'saldo': {
      const j = buscarJornada(jornadas, hoy);
      const cartera = calcularCartera(jornadas, recaudos, hoy);
      const gastosHoy = gastos.filter((g) => String(g.fecha) === hoy)
        .reduce((s, g) => s + num(g.monto), 0);

      let m = 'Hoy ' + fmtFechaCorta(hoy) + '\n';
      if (j) {
        const d = detalleJornada(j, recaudos, hoy);
        m += 'Causado    ' + fmtCOP(d.causado) + '\n' +
             'Recaudado  ' + fmtCOP(d.recaudado) + '  ' + d.estado + '\n';
      } else {
        m += 'Causado    sin reportar\n';
      }
      m += 'Gastos     ' + fmtCOP(gastosHoy) + '\n';
      m += '\n' + bloqueCartera(cartera, cfg);
      return { accion: 'responder', filas: [], mensaje: m };
    }

    case 'pendientes': {
      const cartera = calcularCartera(jornadas, recaudos, hoy);
      if (!cartera.items.length) {
        return { accion: 'responder', filas: [], mensaje: 'Nada pendiente. Todo cobrado. 🟢' };
      }
      const lineas = cartera.items.map((i) => {
        const alerta = i.dias >= cfg.diasAlertaCartera ? '🔴' : '🟡';
        return alerta + ' ' + fmtFechaCorta(i.fecha) + '  ' + fmtCOP(i.saldo) +
          '  · ' + i.dias + (i.dias === 1 ? ' día' : ' días') +
          (i.recaudado > 0 ? '  (de ' + fmtCOP(i.causado) + ')' : '');
      });
      return {
        accion: 'responder', filas: [],
        mensaje: 'Por cobrar · ' + fmtCOP(cartera.total) + ' en ' + cartera.items.length +
          (cartera.items.length === 1 ? ' día' : ' días') + '\n\n' + lineas.join('\n'),
      };
    }

    case 'mes': {
      const r = resumenMes(datos, comando.anio, comando.mes, hoy);
      let m = r.nombreMes.charAt(0).toUpperCase() + r.nombreMes.slice(1) + ' ' + r.anio +
        ' · ' + r.diasRegistrados + (r.diasRegistrados === 1 ? ' día' : ' días') + ' registrados';
      if (r.faltantes.length) {
        m += ', faltan ' + r.faltantes.length +
          (r.faltantes.length <= 5 ? ' (' + r.faltantes.map(fmtFechaCorta).join(', ') + ')' : '');
      }
      m += '\n\n' +
        'Causado    ' + fmtCOP(r.causado) + '\n' +
        'Gastos     ' + fmtCOP(r.gastado) + '\n' +
        '─────────────────────\n' +
        'Resultado  ' + fmtCOP(r.resultado) + '     ¿el negocio va bien?\n\n' +
        'Entró      ' + fmtCOP(r.entro) + '\n' +
        'Salió      ' + fmtCOP(r.salio) + '\n' +
        '─────────────────────\n' +
        'Caja       ' + fmtCOP(r.caja) + '     ¿tengo plata?\n\n' +
        'Cartera    ' + fmtCOP(r.cartera) + '     falta por cobrar';
      return { accion: 'responder', filas: [], mensaje: m };
    }

    case 'ultimos': {
      const movs = []
        .concat(recaudos.map((r) => ({
          id: r.id, fecha: r.fecha, monto: num(r.monto),
          que: 'recibo ' + fmtFechaCorta(String(r.jornada_id || '').replace(/^J-/, '')),
        })))
        .concat(gastos.map((g) => ({
          id: g.id, fecha: g.fecha, monto: -num(g.monto),
          que: 'gasto ' + (g.categoria || ''),
        })))
        .filter((m) => m.id)
        .sort((a, b) => (String(a.id) < String(b.id) ? 1 : -1))
        .slice(0, 5);

      if (!movs.length) return { accion: 'responder', filas: [], mensaje: 'Todavía no hay movimientos.' };
      return {
        accion: 'responder', filas: [],
        mensaje: 'Últimos movimientos\n\n' + movs.map((m) =>
          m.id + '  ' + fmtFechaCorta(m.fecha) + '  ' + fmtCOP(m.monto) + '  ' + m.que).join('\n') +
          '\n\nPara deshacer uno: /anular <id>',
      };
    }

    case 'error':
      return { accion: 'responder', filas: [], mensaje: comando.mensaje };

    case 'ayuda':
    default:
      return { accion: 'responder', filas: [], mensaje: textoAyuda(cfg) };
  }
}

// ────────────────────────────────────────────────────────────
//  Armado de mensajes
// ────────────────────────────────────────────────────────────

/**
 * A qué pestaña va la escritura. Lo usa el nodo Switch de n8n, que así tiene
 * una sola salida por pestaña en vez de una por acción.
 *
 * `anexar_jornada` y `actualizar_jornada` van al mismo lado: el nodo de
 * Sheets usa "append or update" contra la columna `id`, y una jornada tiene
 * un id derivado de su fecha, así que la propia hoja resuelve si es alta o
 * corrección.
 */
function destinoDe(accion) {
  if (accion === 'anexar_jornada' || accion === 'actualizar_jornada') return 'jornadas';
  if (accion === 'anexar_recaudo') return 'recaudos';
  if (accion === 'anexar_gasto') return 'gastos';
  return 'ninguno';
}

function filaRecaudo(recaudosExistentes, hoy, jornadaId, comando) {
  return {
    id: siguienteId('R-', recaudosExistentes),
    // El bot siempre registra con la fecha de hoy; el portal deja escribirla
    // a mano (`fechaCaja`), validada contra futuro en comandoDesdePortal.
    fecha: comando.fechaCaja || hoy,
    jornada_id: jornadaId,
    monto: comando.monto,
    medio: comando.medio || 'efectivo',
    nota: comando.nota || '',
  };
}

function lineaJornada(d) {
  return ICONO_ESTADO[d.estado] + ' ' + fmtFechaCorta(d.fecha) + '  ' + d.estado + '\n' +
    'Causado    ' + fmtCOP(d.causado) + '\n' +
    'Recaudado  ' + fmtCOP(d.recaudado) +
    (d.saldo > 0 ? '\nFaltan     ' + fmtCOP(d.saldo)
      : d.saldo < 0 ? '\nSobran     ' + fmtCOP(-d.saldo) + '  ⚠️' : '');
}

/** La cartera contando una jornada que todavía no está en la hoja. */
function lineaCartera(jornadas, recaudos, hoy, filaNueva) {
  const sinEsa = jornadas.filter((j) => String(j.id) !== String(filaNueva.id));
  const c = calcularCartera(sinEsa.concat([filaNueva]), recaudos, hoy);
  return 'Cartera total: ' + fmtCOP(c.total);
}

/** La cartera contando recaudos que todavía no están en la hoja. */
function lineaCarteraTras(jornadas, recaudos, hoy, filasNuevas) {
  const c = calcularCartera(jornadas, recaudos.concat(filasNuevas), hoy);
  return 'Cartera total: ' + fmtCOP(c.total);
}

function bloqueCartera(cartera, cfg) {
  if (!cartera.items.length) return 'Cartera total  $0  · todo cobrado 🟢';
  const viejo = cartera.items[0];
  return 'Cartera total  ' + fmtCOP(cartera.total) + '  en ' + cartera.items.length +
    (cartera.items.length === 1 ? ' día' : ' días') + '\n' +
    'El más viejo: ' + fmtFechaCorta(viejo.fecha) + ', ' + fmtCOP(viejo.saldo) +
    ', hace ' + viejo.dias + (viejo.dias === 1 ? ' día' : ' días') +
    (viejo.dias >= cfg.diasAlertaCartera ? '  🔴' : '');
}

function textoAyuda(cfg) {
  return 'Cuentas del parqueadero\n' +
    'Los montos van sin puntos: 480000. Sirve 480k.\n' +
    'Las fechas son DD-MM. Si no la ponés, es hoy.\n\n' +
    'REGISTRAR\n' +
    '/dia 480000            lo que produjo hoy\n' +
    '/dia 22-08 480000      lo que produjo ese día\n' +
    '/recibo 300000         plata que te entregaron\n' +
    '/recibo 300000 22-08   abono a un día puntual\n' +
    '/gasto 45000 servicios agua agosto\n' +
    '/deuda 96000 servicios predial     (sin pagar)\n\n' +
    'CONSULTAR\n' +
    '/saldo         hoy y cuánto te deben\n' +
    '/pendientes    días por cobrar\n' +
    '/mes           el resumen del mes\n' +
    '/dia 22-08     el detalle de un día\n\n' +
    'CORREGIR\n' +
    '/ultimos       los últimos 5, con su id\n' +
    '/anular R-000101\n\n' +
    'Categorías: ' + cfg.categorias.join(', ');
}

// ────────────────────────────────────────────────────────────
//  El portal: contrato de docs/api-portal.md
//
//  Nada de esto hashea ni firma: el nodo Code de n8n NO tiene criptografía.
//  Se comprobó contra la instancia real — no hay Web Crypto, no hay
//  require('crypto'), no hay process; solo Buffer. Hashear y firmar lo hace
//  el nodo Crypto de n8n, que es SHA256/HMAC-SHA256 estándar (verificado
//  contra el crypto de Node). Acá solo se arma qué firmar y se compara.
// ────────────────────────────────────────────────────────────

/** Duración del token. Un día de trabajo, y un celular perdido caduca solo. */
const HORAS_TOKEN = 12;

/**
 * El token es `<expira>.<firma>`, sin estado del lado del servidor: la firma
 * es HMAC-SHA256 de `cuerpoAFirmar(expira)` con el secreto del VPS.
 * Verificar es volver a firmar el mismo `expira` y comparar. No hay sesiones
 * que guardar ni que limpiar.
 */
function partirToken(token) {
  const m = String(token || '').match(/^(\d+)\.([a-f0-9]{64})$/);
  if (!m) return null;
  return { expira: Number(m[1]), firma: m[2] };
}

/** Lo que se firma. Una sola definición, para emitir y para verificar. */
function cuerpoAFirmar(expira) {
  return 'pq.v1.' + expira;
}

function expiracion(ahoraSegundos) {
  return Math.floor(ahoraSegundos) + HORAS_TOKEN * 3600;
}

/**
 * Compara sin cortar en la primera diferencia. Contra un atacante remoto la
 * diferencia de tiempo es ruido, pero cuesta cuatro líneas y evita la
 * discusión.
 */
function firmasIguales(a, b) {
  const x = String(a || '');
  const y = String(b || '');
  if (x.length !== y.length) return false;
  let dif = 0;
  for (let i = 0; i < x.length; i++) dif |= x.charCodeAt(i) ^ y.charCodeAt(i);
  return dif === 0;
}

function tokenVigente(expira, ahoraSegundos) {
  return Number(expira) > Math.floor(ahoraSegundos);
}

/** La expiración para mostrarla: "2026-08-23 18:40", hora de Bogotá. */
function fmtExpira(expira) {
  const d = new Date((Number(expira) + OFFSET_HORAS * 3600) * 1000);
  return d.toISOString().slice(0, 10) + ' ' + d.toISOString().slice(11, 16);
}

// ── pq-api-resumen ──────────────────────────────────────────

/**
 * Todo lo que pinta el portal, en una sola respuesta.
 *
 * Dos cosas que el contrato marca y son fáciles de romper:
 *  - `dias` va del más nuevo al más viejo, y un día sin reportar NO aparece:
 *    su fecha va en `mes.faltantes`. Ausencia no es cero.
 *  - `gastos` va al nivel de arriba, no dentro de cada día: un gasto puede
 *    caer en un día sin jornada y anidado desaparecería de la pantalla.
 */
function armarResumen(datos, cfg, anio, mes, hoy) {
  const resumen = resumenMes(datos, anio, mes, hoy);
  const pre = anio + '-' + pad2(mes);
  const enMes = (f) => String(f || '').indexOf(pre) === 0;

  const porJornada = {};
  for (const r of datos.recaudos || []) {
    const k = String(r.jornada_id || '');
    if (!k) continue;
    if (!porJornada[k]) porJornada[k] = [];
    porJornada[k].push({
      id: String(r.id),
      fecha: String(r.fecha),
      monto: num(r.monto),
      medio: r.medio || '',
      nota: r.nota || '',
    });
  }

  const dias = (datos.jornadas || [])
    .filter((j) => enMes(j.fecha))
    .map((j) => {
      const d = detalleJornada(j, datos.recaudos || [], hoy);
      const suyos = (porJornada[d.id] || []).slice().sort((a, b) => (a.id < b.id ? -1 : 1));
      return {
        id: d.id, fecha: d.fecha, causado: d.causado, recaudado: d.recaudado,
        saldo: d.saldo, estado: d.estado, dias: d.dias, nota: d.nota,
        recaudos: suyos,
      };
    })
    .sort((a, b) => (a.fecha < b.fecha ? 1 : -1));

  const gastos = (datos.gastos || [])
    .filter((g) => enMes(g.fecha))
    .map((g) => ({
      id: String(g.id),
      fecha: String(g.fecha),
      fechaPago: g.fecha_pago || '',
      categoria: g.categoria || '',
      monto: num(g.monto),
      descripcion: g.descripcion || '',
      pagadoCon: g.pagado_con || '',
      soporte: g.soporte || '',
    }))
    .sort((a, b) => (a.fecha < b.fecha ? 1 : -1));

  // El mes anterior sale gratis: ya tenemos la hoja entera en memoria.
  const anioPrev = mes === 1 ? anio - 1 : anio;
  const mesPrev = mes === 1 ? 12 : mes - 1;
  const previo = resumenMes(datos, anioPrev, mesPrev, hoy);

  const cartera = calcularCartera(datos.jornadas || [], datos.recaudos || [], hoy);

  const salida = {
    ok: true,
    hoy: hoy,
    mes: resumen,
    dias: dias,
    gastos: gastos,
    serie: seriePorDia(datos, anio, mes, hoy),
    cartera: { total: cartera.total, items: cartera.items },
    config: {
      categorias: cfg.categorias,
      medios: cfg.medios,
      diasAlertaCartera: cfg.diasAlertaCartera,
      nombre: cfg.nombre,
    },
  };
  if (previo.diasRegistrados > 0) {
    salida.comparativo = { resultado: previo.resultado, nombreMes: previo.nombreMes };
  }
  return salida;
}

// ── pq-api-registro ─────────────────────────────────────────

function rechazo(codigo, error) {
  return { tipo: 'rechazo', codigo: codigo, error: error };
}

/**
 * El cuerpo JSON del portal se convierte en el mismo `comando` que produce el
 * parser de Telegram, para que `decidir()` siga siendo el único que sabe qué
 * hacer con él. **El portal es otra `fuente`, no otra lógica.**
 *
 * Devuelve un rechazo con el `codigo` del contrato si algo viene mal.
 */
function comandoDesdePortal(cuerpo, cfg, hoy) {
  const r = interpretarCuerpoPortal(cuerpo, cfg, hoy);
  // Todo comando que salga de acá lleva la fuente puesta. `decidir()` la usa
  // para dos cosas: marcar la fila que escribe, y redactar los mensajes sin
  // sintaxis de comandos de Telegram, que en un formulario web no significan
  // nada. Los rechazos no la llevan: no llegan a `decidir()`.
  return r.tipo === 'rechazo' ? r : { ...r, fuente: 'portal' };
}

function interpretarCuerpoPortal(cuerpo, cfg, hoy) {
  const c = cuerpo || {};
  const tipo = normalizar(c.tipo);

  // Todo lo que sale de aca lleva la fuente puesta. `decidir()` la usa para
  // dos cosas: marcar la fila que escribe, y redactar los mensajes sin
  // sintaxis de comandos que en un formulario web no significan nada.

  // undefined = vino mal. '' = vino vacía y estaba permitido.
  const leerFecha = (v, obligatoria) => {
    if (vacio(v)) return obligatoria ? undefined : '';
    const f = parsearFecha(String(v), hoy);
    return f === null ? undefined : f;
  };
  const leerMonto = (v) => {
    if (vacio(v)) return null;
    const n = num(v);
    return Number.isFinite(n) && n > 0 ? Math.round(n) : null;
  };

  if (tipo === 'jornada') {
    const fecha = leerFecha(c.fecha, true);
    if (fecha === undefined) return rechazo('fecha_invalida', 'Esa fecha no existe.');
    if (fecha > hoy) return rechazo('fecha_invalida', 'Ese dia todavia no pasó.');
    if (vacio(c.causado)) return rechazo('monto_invalido', 'Falta el causado.');
    const causado = num(c.causado);
    if (!Number.isFinite(causado) || causado < 0) {
      return rechazo('monto_invalido', 'El causado tiene que ser un numero de cero para arriba.');
    }
    // Cero es válido a propósito: es el día que no abrió.
    return {
      tipo: 'dia',
      fecha: fecha,
      monto: Math.round(causado),
      nota: c.nota || '',
      confirmar: c.confirmar === true,
    };
  }

  if (tipo === 'recaudo') {
    const fecha = leerFecha(c.fecha, true);
    if (fecha === undefined) return rechazo('fecha_invalida', 'Esa fecha no existe.');
    if (fecha > hoy) return rechazo('fecha_invalida', 'Un recaudo no puede tener fecha futura.');

    const monto = leerMonto(c.monto);
    if (monto === null) return rechazo('monto_invalido', 'El monto tiene que ser mayor que cero.');

    const medio = normalizar(c.medio) || 'efectivo';
    if (cfg.medios.indexOf(medio) === -1) {
      return rechazo('categoria_desconocida', 'No conozco el medio "' + medio + '". Hay: ' + cfg.medios.join(', '));
    }

    const jid = String(c.jornadaId || '').trim();
    if (jid && !/^J-\d{4}-\d{2}-\d{2}$/.test(jid)) {
      return rechazo('fecha_invalida', 'Esa jornada no tiene forma de jornada.');
    }
    return {
      tipo: 'recibo',
      fecha: jid ? jid.slice(2) : null,   // a qué jornada se abona; null = repartir
      fechaCaja: fecha,                   // cuándo llegó la plata
      monto: monto,
      medio: medio,
      nota: c.nota || '',
    };
  }

  if (tipo === 'gasto') {
    const fecha = leerFecha(c.fecha, true);
    if (fecha === undefined) return rechazo('fecha_invalida', 'Esa fecha no existe.');
    const fechaPago = leerFecha(c.fechaPago, false);
    if (fechaPago === undefined) return rechazo('fecha_invalida', 'La fecha de pago no existe.');

    const monto = leerMonto(c.monto);
    if (monto === null) return rechazo('monto_invalido', 'El monto tiene que ser mayor que cero.');

    const categoria = normalizar(c.categoria);
    if (cfg.categorias.indexOf(categoria) === -1) {
      return rechazo('categoria_desconocida', 'No conozco la categoria "' + categoria + '". Hay: ' + cfg.categorias.join(', '));
    }
    return {
      tipo: 'gasto',
      fecha: fecha,
      monto: monto,
      categoria: categoria,
      descripcion: c.descripcion || '',
      pagado: fechaPago !== '',
      fechaPago: fechaPago,
      pagadoCon: normalizar(c.pagadoCon) || 'caja',
    };
  }

  if (tipo === 'anular') {
    const id = String(c.id || '').toUpperCase().trim();
    if (!/^[RG]-\d+$/.test(id)) return rechazo('no_existe', 'Ese id no tiene forma de id.');
    return { tipo: 'anular', id: id };
  }

  return rechazo('tipo_desconocido', 'No sé qué es "' + String(c.tipo || '') + '".');
}

/**
 * La respuesta de pq-api-registro: el mismo `mensaje` que contestaría el bot,
 * más el estado de la jornada tocada. Que las dos vías digan exactamente lo
 * mismo es lo que evita tener que aprender dos sistemas.
 */
function respuestaRegistro(salida, datos, hoy) {
  const r = { ok: true, mensaje: salida.mensaje };
  const filas = salida.filas || [];

  // Las filas que se acaban de escribir todavía no están en `datos`: hay que
  // sumarlas a mano para que el saldo que se devuelve sea el de después.
  const jornadas = (datos.jornadas || []).slice();
  for (const f of filas) {
    if (String(f.id || '').indexOf('J-') !== 0) continue;
    const i = jornadas.findIndex((j) => String(j.id) === String(f.id));
    if (i >= 0) jornadas[i] = f; else jornadas.push(f);
  }
  const recaudos = (datos.recaudos || []).concat(filas.filter((f) => f.jornada_id));

  const idJ = filas
    .map((f) => f.jornada_id || (String(f.id || '').indexOf('J-') === 0 ? f.id : null))
    .find(Boolean);

  if (idJ) {
    const j = jornadas.find((x) => String(x.id) === String(idJ));
    if (j) {
      const d = detalleJornada(j, recaudos, hoy);
      r.jornada = {
        id: d.id, causado: d.causado, recaudado: d.recaudado,
        saldo: d.saldo, estado: d.estado,
      };
    }
  }
  r.cartera = calcularCartera(jornadas, recaudos, hoy).total;
  if (salida.codigo) r.codigo = salida.codigo;
  return r;
}

// ────────────────────────────────────────────────────────────
//  Recordatorio diario
// ────────────────────────────────────────────────────────────

/**
 * Devuelve el aviso del día, o null si no hay nada que decir.
 * El bot que escribe todos los días sin motivo se vuelve ruido y se ignora.
 */
function armarRecordatorio(datos, hoy, cfg) {
  const avisos = [];
  const ayer = sumarDias(hoy, -1);

  if (!buscarJornada(datos.jornadas, ayer)) {
    avisos.push('No registraste lo del ' + fmtFechaCorta(ayer) + '. ¿Cuánto produjo?\n' +
      '/dia ' + fmtFechaCorta(ayer) + ' <monto>');
  }

  const cartera = calcularCartera(datos.jornadas, datos.recaudos, hoy);
  const viejos = cartera.items.filter((i) => i.dias >= cfg.diasAlertaCartera);
  if (viejos.length) {
    avisos.push('Por cobrar hace rato:\n' + viejos.map((i) =>
      '🔴 ' + fmtFechaCorta(i.fecha) + '  ' + fmtCOP(i.saldo) + '  · ' + i.dias + ' días').join('\n'));
  }

  if (hoy.slice(8) === '01') {
    const mesPasado = sumarDias(hoy, -1);
    const r = resumenMes(datos, Number(mesPasado.slice(0, 4)), Number(mesPasado.slice(5, 7)), hoy);
    avisos.push('Cerró ' + r.nombreMes + '.\n' +
      'Resultado ' + fmtCOP(r.resultado) + ' · caja ' + fmtCOP(r.caja) +
      ' · cartera ' + fmtCOP(r.cartera));
  }

  return avisos.length ? avisos.join('\n\n') : null;
}

