/** Filas → CSV. Comillas dobles siempre: es lo que menos sorpresas da. */
function filasACsv(filas, columnas) {
  const esc = (v) => '"' + String(v === null || v === undefined ? '' : v).replace(/"/g, '""') + '"';
  const cuerpo = filas.map((f) => columnas.map((c) => esc(f[c])).join(','));
  return [columnas.join(','), ...cuerpo].join('\n');
}

