/**
 * Nodos "Filas jornada" / "Filas recaudo" / "Filas gasto" de pq-telegram.
 *
 * "Decidir" devuelve un solo item con un arreglo `filas` adentro. Google
 * Sheets necesita un item por fila, así que esto las abre.
 *
 * Va aparte de logica.js a propósito: son tres nodos y no necesitan nada de
 * la lógica de negocio. Inyectar el archivo completo tres veces hacía que el
 * workflow pesara 250 KB y que el editor de n8n se arrastrara.
 */
function correrExpandirFilas() {
  const filas = $input.first().json.filas || [];
  return filas.map((f) => ({ json: f }));
}


return correrExpandirFilas();

